<script setup>
import {saveLocalProductImage} from '../../../../web/local-product-image.js';
import ProductionProductFields from './ProductionProductFields.vue';
import {computed,ref,reactive,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {productionProductFields,normalizeProductionProduct,normalizeProductionOrder,productionLines} from '../../../../web/production-edit.js';
import {quotationText} from '../../../../web/quotation-presentation.js';
const props=defineProps({group:String,record:Object,creating:Boolean,data:Object,saveRecord:Function});const emit=defineEmits(['close']);
const dialog=ref(null),success=ref(null),editing=ref(!!props.creating),saving=ref(false),error=ref(''),current=ref(props.record),picker=ref(''),quantity=ref(1);
const product=computed(()=>props.group==='products'),title=computed(()=>product.value?'producto':'orden de producción');
const imageFile=ref(null),imageVersion=ref(0);
const form=reactive({}),lines=ref([]);const id=props.record?.id||'new_'+crypto.randomUUID();
const editable=computed(()=>props.data?.canEdit&&(product.value||!current.value||current.value.status==='CREATED'));
const directory=computed(()=>props.data?.directory||{}),accounts=computed(()=>directory.value.customers||[]),contacts=computed(()=>(directory.value.contacts||[]).filter(c=>c.customerId===form.accountId)),quotes=computed(()=>(directory.value.quotations||[]).filter(q=>q.customerId===form.accountId));
const labels={code:'Código',name:'Nombre',description:'Descripción',checklist:'Lista de verificación',techSpecs:'Especificaciones técnicas',comments:'Comentarios'};
const host=(()=>{try{return window.parent.location.origin===window.location.origin?window.parent.document.body:document.body;}catch{return document.body;}})();let opener;
function reset(){imageFile.value=null;const r=current.value||{};Object.assign(form,r);form.items=(r.items||[]).map(i=>({...i}));form.processes=(r.processes||[]).map(p=>({...p}));for(const k of Object.keys(productionProductFields))form[k]=quotationText(r[k]||'');Object.assign(form,{cost:r.cost??'',price:r.price??0,tax:r.tax??19,date:r.date||new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),deliveryDate:r.deliveryDate||'',accountId:r.accountId||'',contactId:r.contactId||'',quotationId:r.quotationId?String(r.quotationId).replace(/^(\d+)$/,'legacy-quotation-$1'):''});lines.value=(r.lines||[]).map(l=>({...l,serial:l.serial||''}));}
function edit(){reset();editing.value=true;error.value='';}
function changeQuotation(){const q=(directory.value.quotations||[]).find(q=>q.id===form.quotationId);if(!q)return;if(form.accountId!==q.customerId){form.accountId=q.customerId;form.contactId='';}if(q.contactId&&(directory.value.contacts||[]).some(c=>c.id===q.contactId&&c.customerId===q.customerId))form.contactId=q.contactId;}
function changeAccount(){form.contactId='';form.quotationId='';}
function add(){const p=props.data.products.find(p=>p.id===picker.value);if(!p)return;try{const [n]=productionLines([{productId:p.id,quantity:quantity.value}],props.data.products);lines.value.push(n.line);error.value='';}catch(e){error.value=e.message;}}
function close(){if(saving.value)return;dialog.value?.close();success.value?.close();emit('close');opener?.focus?.();}
async function save(){if(saving.value||!editable.value||!props.data.writeEnabled)return;saving.value=true;error.value='';try{const input={...form,lines:lines.value.map(l=>({...l}))};if(product.value)normalizeProductionProduct(input);else{normalizeProductionOrder(input,directory.value,current.value);productionLines(input.lines,props.data.products);}current.value=await props.saveRecord(props.group,id,current.value,input);if(product.value&&imageFile.value){try{await saveLocalProductImage(id,imageFile.value);imageVersion.value=Date.now();}catch(e){throw Error('Los datos del producto se guardaron, pero la imagen no: '+e.message+' Puedes volver a guardar para reintentar.');}}reset();editing.value=false;await nextTick();success.value.showModal();}catch(e){error.value=e.code==='permission-denied'?'No tienes permiso para guardar.':e.message||'No se pudo guardar.';}finally{saving.value=false;}}
function accept(){success.value.close();}
onMounted(()=>{opener=host.ownerDocument.activeElement;reset();dialog.value.showModal();});onBeforeUnmount(()=>{dialog.value?.close();success.value?.close();});
</script>
<template><Teleport :to="host"><link rel="stylesheet" href="/procesos/account-detail.css">
<dialog ref="dialog" class="sigmyp-account-dialog sigmyp-editable-account-dialog sigmyp-production-dialog" :class="{'sigmyp-production-product-dialog':product,'sigmyp-production-order-dialog':!product}" aria-labelledby="production-editor-title" @cancel.prevent="close">
<header class="sigmyp-account-header"><h2 id="production-editor-title">{{ current?(current.number||current.name):'Crear '+title }}</h2><button type="button" class="sigmyp-account-close" :disabled="saving" @click="close">Cerrar ✕</button></header>
<div class="sigmyp-record-scroll"><form id="production-editor-form" class="sigmyp-account-form" @submit.prevent="save"><fieldset :disabled="saving||!editing">
<ProductionProductFields v-if="product" :form="form" :record="current" :editing="editing" :image-file="imageFile" :image-version="imageVersion" @image-selected="imageFile=$event" :catalog="data.purchases?.items||[]" :suppliers="data.purchases?.suppliers||[]" />
<div v-else class="production-order-form"><section class="production-order-sidebar"><h3>Orden de producción</h3><div class="production-order-body"><label v-if="current">Número<input :value="current.number" disabled></label><label>Cotización<select v-model="form.quotationId" required @change="changeQuotation"><option value="">Selecciona una cotización</option><option v-for="q in (directory.quotations||[])" :key="q.id" :value="q.id">{{ q.number }}</option><option v-if="form.quotationId&&!(directory.quotations||[]).some(q=>q.id===form.quotationId)" :value="form.quotationId">{{ current?.quotationNumber||form.quotationId }} · referencia histórica</option></select></label><label>Cuenta<select v-model="form.accountId" required @change="changeAccount"><option value="">Selecciona una cuenta</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.name }}</option></select></label><label>Contacto<select v-model="form.contactId"><option value="">Sin contacto</option><option v-for="c in contacts" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>Creación<input v-model="form.date" type="date" required :disabled="!!current" min="2026-01-01" max="2026-12-31"></label>
<fieldset class="production-stage"><legend>Verificación</legend><label>Verificó<input :value="current?.verifiedByName||'Sin registrar'" disabled></label><label>Fecha de verificación<input :value="current?.verificationDate||current?.technicalApprovalDate||'Sin registrar'" disabled></label></fieldset>
<fieldset class="production-stage"><legend>Entrega de ítems</legend><label>Responsable de entrega de ítems<input :value="current?.itemsDeliveryResponsibleName||'Sin registrar'" disabled></label><label>Ítems recibidos por<input :value="current?.itemsReceivedByName||'Sin registrar'" disabled></label><label>Fecha de entrega de ítems<input :value="current?.itemsDeliveryDate||'Sin registrar'" disabled></label></fieldset>
<fieldset class="production-stage"><legend>Entrega de productos</legend><label>Responsable de entrega<input :value="current?.deliveryResponsibleName||'Sin registrar'" disabled></label><label>Fecha esperada<input v-model="form.deliveryDate" type="date" required :min="form.date"></label><label>Aprobó<input :value="current?.approvedByName||'Sin registrar'" disabled></label><label>Aprobación<input :value="current?.approvalDate||'Sin registrar'" disabled></label></fieldset><label>Estado<input :value="({CREATED:'Creado',VERIFIED:'Verificado',ITEMS_DELIVERED:'Ítems entregados',DELIVERED:'Entregado',APPROVED:'Aprobado',FINISHED:'Finalizado',VOIDED:'Anulado'})[current?.status]||'Creado'" disabled></label><label>Comentarios<textarea v-model="form.comments" rows="5" maxlength="4000"></textarea></label></div></section>
<section class="production-order-products"><h3>Productos</h3><div class="production-order-body"><div v-if="editing" class="production-picker"><label>Producto<select v-model="picker"><option value="">Selecciona un producto</option><option v-for="p in data.products" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label>Código<select v-model="picker"><option value="">Selecciona un código</option><option v-for="p in data.products" :key="p.id" :value="p.id">{{ p.code }}</option></select></label><label>Cantidad<input v-model="quantity" type="number" min="0.001" max="1000000000" step="0.001"></label><button type="button" :disabled="!picker" @click="add">Agregar</button></div><div class="sigmyp-account-table-scroll"><table class="production-lines"><thead><tr><th>Código</th><th>Producto</th><th>Cantidad</th><th>Serial</th><th>Comentarios</th><th v-if="editing">Acciones</th></tr></thead><tbody><tr v-for="(line,i) in lines" :key="i"><td>{{ line.code }}</td><td>{{ line.name }}</td><td><input v-if="editing" v-model="line.quantity" aria-label="Cantidad del producto" type="number" min="0.001" max="1000000000" step="0.001" required><span v-else>{{ line.quantity }}</span></td><td><input v-if="editing" v-model="line.serial" aria-label="Serial" maxlength="500"><span v-else>{{ line.serial||'—' }}</span></td><td><textarea v-if="editing" v-model="line.comments" aria-label="Comentarios del producto" maxlength="2000"></textarea><span v-else>{{ line.comments||'—' }}</span></td><td v-if="editing"><button type="button" title="Quitar producto" aria-label="Quitar producto" @click="lines.splice(i,1)">×</button></td></tr><tr v-if="!lines.length"><td colspan="6">Agrega los productos de la orden.</td></tr></tbody></table></div></div></section></div>
</fieldset></form><p v-if="error" role="alert" class="sigmyp-account-save-status">{{ error }}</p></div>
<footer class="sigmyp-account-footer"><p v-if="!data.writeEnabled">El guardado está pendiente de habilitación.</p><p v-if="!product&&current&&current.status!=='CREATED'">Esta orden se conserva en consulta por su estado.</p><div class="sigmyp-account-edit-actions"><button v-if="!editing&&editable" type="button" @click="edit">Actualizar datos</button><button v-if="editing" type="submit" form="production-editor-form" :disabled="saving||!data.writeEnabled">{{ saving?'Guardando…':current?'Guardar cambios':'Crear '+title }}</button><button v-if="editing&&current" type="button" :disabled="saving" @click="reset();editing=false">Cancelar edición</button><button type="button" :disabled="saving" @click="close">Cerrar</button></div></footer>
</dialog><dialog ref="success" class="sigmyp-account-success" role="alertdialog" aria-labelledby="production-success-title" @cancel.prevent="accept"><span class="sigmyp-account-success-icon">✓</span><h2 id="production-success-title">Guardado exitoso</h2><p>Los datos se guardaron correctamente.</p><button type="button" autofocus @click="accept">Aceptar</button></dialog></Teleport></template>
